import type { RankName } from '../domain/rank.js';

/**
 * Discord application emoji names. The matching PNGs are generated by
 * scripts/import-rank-assets.mjs and uploaded by scripts/sync-application-emojis.mjs.
 */
export const RANK_EMOJI_NAMES: Readonly<Partial<Record<RankName, string>>> = {
  'Bronze 1': 'rank_bronze_1',
  'Bronze 2': 'rank_bronze_2',
  'Bronze 3': 'rank_bronze_3',
  'Silver 1': 'rank_silver_1',
  'Silver 2': 'rank_silver_2',
  'Silver 3': 'rank_silver_3',
  'Gold 1': 'rank_gold_1',
  'Gold 2': 'rank_gold_2',
  'Gold 3': 'rank_gold_3',
  'Platinum 1': 'rank_platinum_1',
  'Platinum 2': 'rank_platinum_2',
  'Platinum 3': 'rank_platinum_3',
  'Diamond 1': 'rank_diamond_1',
  'Diamond 2': 'rank_diamond_2',
  'Diamond 3': 'rank_diamond_3',
  'Master 1': 'rank_master_1',
  'Master 2': 'rank_master_2',
  'Master 3': 'rank_master_3',
  Grandmaster: 'rank_grandmaster',
  Pending: 'rank_pending',
  Unranked: 'rank_unranked',
};

/**
 * Returns a Discord custom-emoji token such as <:rank_gold_1:123>, or an
 * empty string when the application emoji has not been synchronized yet.
 */
export function getRankEmojiTag(
  rank: RankName,
  applicationEmojiTags: ReadonlyMap<string, string>,
): string {
  const emojiName = RANK_EMOJI_NAMES[rank];
  return emojiName ? (applicationEmojiTags.get(emojiName) ?? '') : '';
}
